function dpL10nSample(v){if(typeof v!=='string'||typeof state==='undefined')return v;if(state.lang==='zh')return toSimplified(v);if(state.lang==='zht')return toTraditional(v);if(!['en','ko'].includes(state.lang))return v;const m=dpCannedTranslations[v];return m?m[state.lang==='en'?0:1]:v;}

const esc=s=>String(dpL10nSample(s??'')).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

