function dpMomentShareLine(){const x=dpMomentStats();return x?`<div class="dp-share-data">${x.e.date} · ${dpTime(x.e.minute)}<br>${label3('心率','Heart','심박')} ${Math.round(x.beforeH)} → ${Math.round(x.afterH)} bpm<br>${label3('呼吸','Breathing','호흡')} ${x.beforeR.toFixed(0)} → ${x.afterR.toFixed(0)} /min</div>`:'';}
