homeView=function(){const root=dom(oldHome());root.querySelector('.me-heart-moment-entry')?.remove();root.querySelectorAll('.dp-lane-description').forEach(e=>e.remove());const summary=root.querySelector('.dp-combined-summary');if(summary)summary.classList.add('dp68-summary');const prev=root.querySelector('.dp67-home-card');const focus=root.querySelector('.dp-today-focus');if(prev&&focus)focus.parentNode.insertBefore(prev,focus);return html(root);};

// B. Single distinctive prevention button. SVG here is decorative and doesn't duplicate content.
const heartLungSVG=`<svg class="dp68-cardio-art" viewBox="0 0 250 145" aria-hidden="true"><defs><linearGradient id="dp68gl" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b0fff6"/><stop offset="1" stop-color="#6cc7ff"/></linearGradient></defs><g fill="none" stroke="url(#dp68gl)" stroke-width="3.5" stroke-linecap="round" opacity=".72"><path d="M101 56 Q90 40 70 53 Q42 68 40 101 Q43 124 66 121 Q89 115 105 95 Q111 85 110 67"/><path d="M142 56 Q154 40 177 53 Q203 66 207 101 Q203 122 178 121 Q155 114 138 95 Q130 84 134 66"/><path d="M123 26v41m0-12-14 14m14-14 14 14"/><path d="M20 84 h36 l12-16 10 36 16-26 11 6 h28 l12-20 10 42 12-23 h61" stroke-width="2.5" opacity=".67"/></g></svg>`;
dp67HomePrevention=function(){const D=dp67PreventionData(),p=D.p;const elevated=[D.heart,D.breath].some(x=>x.grade>=2);return `<button class="card dp68-prevent-button dp67-home-card" data-action="nav" data-page="health" aria-label="${L('查看心肺預防重點','查看心肺預防重點','View heart and breathing prevention','심폐 예방 관리 보기')}">${heartLungSVG}<div class="dp68-prevent-body"><span class="dp68-prevent-eyebrow">${L('預防性健康管理','預防性健康管理','Preventive health care','예방 건강 관리')}</span><b>${L('心肺預防','心肺預防','Heart & Breathing Prevention','심폐 예방 관리')}</b><p>${elevated?L('近期出現需要優先確認的心肺變化','近期出現需要優先確認的心肺變化','Recent changes deserve a closer look','최근 변화를 확인해 주세요'):L('依品種、年齡與體重，掌握日常應留意的重點','依品種、年齡與體重，掌握日常應留意的重點','Understand what to watch for this pet','품종·나이·체중에 따른 주요 관찰 사항')}</p><small>${esc(breedText(p))} · ${Number(p.age).toFixed(1)} ${t('years')} · ${Number(p.weight).toFixed(1)} kg</small></div><span class="dp68-prevent-arrow">${vicon('chev',24)}</span></button>`;};

// C. Prevention: make detailed breed/age/weight watch priorities the focus in Health.
dp67WatchMain=function(){const D=dp67PreventionData(),p=D.p,items=dp67WatchItems(p,D.type);const count=items.length;const visible=items.slice(0,3);return `<section class="dp67-prevention dp68-prevent-main" aria-label="${L('心肺預防','心肺預防','Heart & Breathing Prevention','심폐 예방 관리')}"><div class="dp67-hero"><div class="dp67-eyebrow">${L('預防性健康管理','預防性健康管理','PREVENTIVE HEALTH','예방 건강 관리')}</div><h2>${L('心肺預防','心肺預防','Heart & Breathing Prevention','심폐 예방 관리')}</h2><p>${L('AI 輔助整理這隻寵物值得優先留意的事項','AI 輔助整理這隻寵物值得優先留意的事項','AI-assisted priorities for your pet','AI 보조로 정리한 주요 관찰 사항')}</p><div class="dp67-profile"><span>${esc(breedText(p))}</span><span>${Number(p.age).toFixed(1)} ${t('years')}</span><span>${Number(p.weight).toFixed(1)} kg</span></div></div><div class="dp68-watch-intro"><b>${L('依牠的條件，需要留意哪些健康變化？','依牠的條件，需要留意哪些健康變化？','What should you watch for?','어떤 변화를 관찰해야 할까요?')}</b><p>${L('綜合品種、年齡、體重與長期照護知識，整理出更有行動價值的預防建議。','綜合品種、年齡、體重與長期照護知識，整理出更有行動價值的預防建議。','Guidance based on breed, age, weight and preventive-care references.','품종·나이·체중과 예방 관리 정보를 바탕으로 안내합니다.')}</p><span class="dp68-watch-count">${L(`${count} 項留意方向`,`${count} 項留意方向`,`${count} areas to watch`,`${count}개 관찰 항목`)}</span></div><div class="dp68-watch-list">${visible.map((it,i)=>`<article class="dp68-watch-card"><div class="dp68-watch-card-head"><span>${String(i+1).padStart(2,'0')}</span><h3>${it.name}</h3></div><div class="dp68-watch-copy"><b>${L('為什麼留意','為什麼留意','Why it matters','관찰 이유')}</b><p>${it.body}</p><b>${L('建議做法','建議做法','What to do','권장 사항')}</b><p>${it.action}</p></div></article>`).join('')}</div>${items.length>3?`<details class="dp68-expand-watch"><summary>More · ${L('其餘預防重點','其餘預防重點','Additional prevention priorities','추가 예방 관리')}</summary>${items.slice(3).map(it=>`<article class="dp68-watch-card"><h3>${it.name}</h3><p>${it.body}</p><p>${it.action}</p></article>`).join('')}</details>`:''}<div class="dp68-prevent-note">${L('目前使用內建的預防規則與模擬資料，並非雲端 AI 診斷或已驗證的疾病預測。','目前使用內建的預防規則與模擬資料，並非雲端 AI 診斷或已驗證的疾病預測。','Uses built-in care rules and demo readings—not a cloud AI diagnosis or validated disease prediction.','내장 예방 관리 규칙과 데모 수치를 사용하며 진단이나 검증된 질병 예측이 아닙니다.')}</div><div class="dp67-prevent-actions"><button type="button" data-action="deep-category" data-index="0">${L('查看心肺分析','查看心肺分析','Open heart & breathing analysis','심폐 분석 보기')} →</button><button type="button" data-action="health-detail" data-page="notes">${L('記錄觀察','記錄觀察','Record an observation','관찰 기록하기')} →</button></div></section>`;};

// D. Health alerts: show three, then More. No duplicate condition panels.
function moreList(items,renderer){const first=items.slice(0,3),extra=items.slice(3);return first.length?renderer(first)+(extra.length?`<details class="dp68-more"><summary>More · ${extra.length} ${L('項','項','more','건')}</summary>${renderer(extra)}</details>`:''):'';}
const oldUpcoming=dpUpcomingCareItems;
dpUpcomingCareItems=function(){if(selectedBlank()||dp58FreshPet())return [];const today=iso(localDate()),items=[],tomorrow=iso(dateAdd(localDate(),1));const med=dpMedDue(tomorrow).filter(x=>x.status==='pending');for(const m of med.slice(0,12))items.push({date:tomorrow,page:'med',icon:'med',title:label3('下次用藥','Next medication','다음 투약')+' · '+dpL10nSample(m.name),detail:label3('明天','Tomorrow','내일')+' · '+m.time});for(const v of allVaxForDog().filter(x=>x.status==='upcoming'&&x.date>today).slice(0,12))items.push({date:v.date,page:'vaccines',icon:'vaccine',title:label3('下次疫苗接種','Next vaccination','다음 예방접종')+' · '+dpL10nSample(v.name),detail:dpFullDate(v.date)});for(const w of dpWormRows().filter(x=>x.nextDate&&x.nextDate>today).slice(0,12))items.push({date:w.nextDate,page:'deworming',icon:'vaccine',title:label3('下次驅蟲','Next deworming','다음 구충')+' · '+w.brand,detail:dpFullDate(w.nextDate)});return items.sort((a,b)=>a.date.localeCompare(b.date)).slice(0,40);};
healthView=function(){const root=dom(oldHealth());if(state.detail)return html(root);const $=sel=>root.querySelector(sel);const menu=$('.care-menu');const oldFood=$('.food-feature');if(menu&&oldFood){const d=currentDog(),consumed=todayFood(),target=targetFood();menu.insertAdjacentHTML('afterbegin',`<button class="health-item dp68-food-link" data-action="health-detail" data-page="food"><span class="thumb" style="background:#fff3df">${vicon('food',23)}</span><span class="grow"><span class="lbl">${t('food')}</span><span class="hint">${L('飲食目標與每日食量','飲食目標與每日食量','Food target and daily feeding','식사 목표 및 일일 급여량')} · ${consumed}/${target} kcal</span></span>${vicon('chev',19)}</button>`);oldFood.remove();}
 if(menu){for(const page of ['notes','recovery-care']){const btn=menu.querySelector(`.health-item[data-page="${page}"]`);if(btn){const card=document.createElement('section');card.className='card dp68-independent-care';card.appendChild(btn);menu.parentNode.insertBefore(card,menu.nextSibling);}}}
 const oldAge=$('.dp67-age');oldAge?.remove();
 const today=dpTodayCareItems(),upcoming=dpUpcomingCareItems();const todo=$('.care-todo:not(.dp-upcoming-care)'),up=$('.dp-upcoming-care');if(todo&&today.length)todo.innerHTML=moreList(today,dpHealthTodayTasksMarkup);if(up&&upcoming.length)up.innerHTML=moreList(upcoming,dpUpcomingCareMarkup);else if(up&&!upcoming.length)up.innerHTML=dpUpcomingCareMarkup([]);
 return html(root);};

// E. Me: biological-age card above baseline; Heart Moment under baseline.
function ageMe(){const valid=signalQuality().valid;const bio=valid?bioAgeDelta().bio.toFixed(1):'—';return `<section class="card dp68-age-me"><details><summary><span class="dp68-age-icon" aria-hidden="true">${vicon('activity',26)}</span><span class="dp68-age-text"><b>${L('AI 推算生理年齡','AI 推算生理年齡','AI-estimated Biological Age','AI 추정 생체 나이')}</b><small>${L('長期變化 · 點擊查看 30 天趨勢','長期變化 · 點擊查看 30 天趨勢','Long-term estimate · open 30-day trend','장기 추정 · 30일 추세 보기')}</small></span><strong>${bio} <small>${t('years')}</small></strong></summary><div class="dp68-age-expanded"><p>${L('模型估算值，適合看長期變化，不代表診斷或實際壽命。','模型估算值，適合看長期變化，不代表診斷或實際壽命。','A model estimate for longer-term context—not a diagnosis or actual lifespan.','장기 추세를 위한 모델 추정치이며 진단이나 실제 수명이 아닙니다.')}</p>${valid?ageTrendCard(true):''}<button class="cta secondary full" data-action="age-detail">${L('查看詳細說明','查看詳細說明','View details','자세히 보기')}</button></div></details></section>`;}
function heartMomentMe(){return `<button class="card me-heart-moment-entry dp68-me-heart" data-action="heart-moment" aria-label="${L('打開心跳時刻','打開心跳時刻','Open Heart Moments','심장 순간 열기')}"><div class="me-heart-art">${heartFeatureArt()}</div><div class="me-heart-content"><div class="me-heart-label">${L('心跳時刻','心跳時刻','Heart Moments','심장 순간')}</div><div class="me-heart-desc">${L('保存這隻寵物的心跳紀念','保存這隻寵物的心跳紀念','Capture a keepsake of this pet’s heartbeat','반려동물의 심박 순간을 간직하세요')}</div><span class="me-heart-action">${L('開啟','開啟','Open','열기')} ${vicon('chev',15)}</span></div></button>`;}
meView=function(){const root=dom(oldMe());const baseline=root.querySelector('.dp-owner-baseline-me');if(baseline){baseline.insertAdjacentHTML('beforebegin',ageMe());baseline.insertAdjacentHTML('afterend',heartMomentMe());}return html(root);};
const oldFreshHome=dp58FreshHome,oldFreshMe=dp58FreshEmptyTab;
dp58FreshHome=function(){const root=dom(oldFreshHome());root.querySelector('.dp58-heart-entry')?.remove();root.querySelector('[data-action="heart-moment"]')?.remove();return html(root);};
dp58FreshEmptyTab=function(){const root=dom(oldFreshMe());if(state.tab==='me'){root.querySelector('.dp58-first-empty')?.insertAdjacentHTML('afterend',heartMomentMe());}return html(root);};

// Blank profile also keeps Heart Moments in Me; user must enter a name and photo first.
const oldBlankHome=blankHomeView,oldBlankMe=blankMeView;
blankHomeView=function(){const root=dom(oldBlankHome());root.querySelector('.dp58-blank-heart')?.remove();return html(root);};
blankMeView=function(){const root=dom(oldBlankMe());const anchor=root.querySelector('.empty-profile-card');if(anchor)anchor.insertAdjacentHTML('afterend',`<button class="card dp68-blank-heart" data-action="heart-blank">${vicon('heart',21)} <b>${L('心跳時刻','心跳時刻','Heart Moments','심장 순간')}</b><span>${L('先填入寵物名稱與照片','先填入寵物名稱與照片','Add name and photo first','이름과 사진을 먼저 등록하세요')}</span>${vicon('chev',17)}</button>`);return html(root);};

// F. Deep 7/30-day heart & breathing: condition summary for each date; curves optional.
function dailyGrade(score){return score>=90?0:score>=80?1:score>=60?2:3;}
function gradeLabel(g){return g<0?L('無資料','無資料','No data','데이터 없음'):[L('正常','正常','Normal','정상'),L('輕風險','輕風險','Low Risk','낮은 주의'),L('中風險','中風險','Middle Risk','중간 주의'),L('高風險','高風險','High Risk','높은 주의')][g];}
function gradeShort(g){return g<0?L('—','—','—','—'):[L('正常','正常','Normal','정상'),L('輕','輕','Low','낮음'),L('中','中','Med','중간'),L('高','高','High','높음')][g];}
function gradeColor(g){return ['#18996d','#3788e6','#e69a35','#d65c68'][Math.max(0,g)];}
function periodHeart(days,cp){const rows=dayRowsWithIndex(days),valid=rows.filter(r=>validDaySample(r,r.idx).valid);if(!valid.length)return `<section class="card"><h2>${L('這段時間有效資料不足','這段時間有效資料不足','Not enough valid days','유효한 기록이 부족합니다')}</h2></section>`;const mean=vals=>vals.reduce((a,b)=>a+b,0)/vals.length;const scores=valid.map(r=>dpHeartComposite(r)),heartMean=mean(valid.map(r=>Number(r.heart))),breathMean=mean(valid.map(r=>Number(r.breath))),avg=Math.round(mean(scores)),counts=[0,0,0,0],states=rows.map(row=>{const ok=validDaySample(row,row.idx).valid,s=ok?dpHeartComposite(row):null,g=ok?Math.max(dailyGrade(s),dp66VitalGrade(row,'heart'),dp66VitalGrade(row,'breath')):-1;if(g>=0)counts[g]++;return {row,s,g};});const dayCards=states.map(({row,s,g})=>`<button class="dp68-risk-day dp68-risk-${g}" data-action="deep-day-view" data-date="${row.date}" title="${row.date} · ${gradeLabel(g)}"><b>${row.date.slice(5).replace('-','/')}</b><i></i><span>${gradeShort(g)}</span></button>`).join('');return `<section class="card dp68-period-heart"><div class="dp68-period-overall"><div><h2>${L('心肺綜合狀態','心肺綜合狀態','Heart & Breathing Overview','심폐 종합 상태')}</h2><p>${L(`${days} 天中 ${valid.length} 天有有效資料`,`${days} 天中 ${valid.length} 天有有效資料`,`${valid.length} valid days out of ${days}`,`${days}일 중 유효 ${valid.length}일`)}</p></div>${dpDeepDottedScore(avg,'#cf6684')}</div><h3>${L('每日心肺狀態','每日心肺狀態','Daily heart & breathing status','일별 심폐 상태')}</h3><p class="dp68-period-lead">${L('點擊日期，可查看當天心跳與呼吸詳情。','點擊日期，可查看當天心跳與呼吸詳情。','Tap any date to review heart and breathing details.','날짜를 누르면 심박과 호흡을 자세히 볼 수 있어요.')}</p><div class="dp68-risk-counts">${counts.map((n,g)=>`<div class="dp68-risk-count dp68-risk-${g}"><b>${n}</b><small>${gradeLabel(g)}</small></div>`).join('')}</div><div class="dp68-risk-calendar ${days===7?'is-week':'is-month'}">${dayCards}</div><p class="dp68-period-avg">${L('期間平均','期間平均','Period averages','기간 평균')} · ${L('心率','心率','Heart rate','심박수')} <b>${heartMean.toFixed(0)} bpm</b> · ${L('呼吸','呼吸','Breathing','호흡')} <b>${breathMean.toFixed(1)} /min</b></p><details class="dp68-period-trends"><summary>${L('展開心跳與呼吸趨勢圖','展開心跳與呼吸趨勢圖','Show heart & breathing charts','심박·호흡 그래프 펼치기')}</summary>${dpOwnerPeriodMetricChart(valid,'heart','#d1708e')}${dpOwnerPeriodMetricChart(valid,'breath','#599ddd')}</details><p class="dp68-data-disclaimer">${L('分級依模擬評分與相對變化整理，用於展示觀察重點，不是已驗證的疾病風險。','分級依模擬評分與相對變化整理，用於展示觀察重點，不是已驗證的疾病風險。','Demo grades summarize wellness scores and relative changes; they are not validated disease-risk levels.','데모 분류는 점수와 상대적 변화를 요약하며 검증된 질병 위험도는 아닙니다.')}</p></section>`;}
