  if(allowPrompt&&!state.dpImageCloudConsent){
   if(!window.confirm(T.approve)){stage.classList.add('dp54-unready');setHint(T.aiOff);return false;}
   state.dpImageCloudConsent=true;if(typeof persist==='function')persist();
  }
