 const slides=[...root.querySelectorAll('.dp-intro-slide')];
 const dots=[...root.querySelectorAll('[data-intro-dot]')];
 const start=root.querySelector('.dp-intro-start-zone');
 let current=0,gesture=null,lock=false;
